func TestPromotedListCommandsReadLocalStore(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("FATHOM_PP_CLI_API_KEY", "test-token")

	db, err := store.OpenWithContext(context.Background(), defaultDBPath("fathom-pp-cli"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}

	fixtures := map[string][]json.RawMessage{
		"meetings": {
			json.RawMessage(`{"recording_id":150816936,"title":"Impromptu Call","created_at":"2026-05-30T00:05:38Z","url":"https://fathom.video/calls/692779236"}`),
		},
		"teams": {
			json.RawMessage(`{"id":"team_1","name":"Core Team"}`),
		},
		"team-members": {
			json.RawMessage(`{"id":"member_1","name":"Gabe Montague","email":"gabe@example.com"}`),
		},
	}
	for resourceType, items := range fixtures {
		stored, failures, err := db.UpsertBatch(resourceType, items)
		if err != nil {
			t.Fatalf("upsert %s: %v", resourceType, err)
		}
		if stored != len(items) || failures != 0 {
			t.Fatalf("upsert %s: stored=%d failures=%d", resourceType, stored, failures)
		}
		if err := db.SaveSyncState(resourceType, "", stored); err != nil {
			t.Fatalf("save sync state %s: %v", resourceType, err)
		}
	}
	if err := db.Close(); err != nil {
		t.Fatalf("close setup store: %v", err)
	}

	for _, command := range []string{"meetings", "teams", "team-members"} {
		t.Run(command, func(t *testing.T) {
			var out, errBuf bytes.Buffer
			var flags rootFlags
			cmd := newRootCmd(&flags)
			cmd.SetOut(&out)
			cmd.SetErr(&errBuf)
			cmd.SetArgs([]string{command, "--agent", "--data-source", "local"})

			if err := cmd.Execute(); err != nil {
				t.Fatalf("%s failed: %v\nstderr: %s", command, err, errBuf.String())
			}

			var got struct {
				Meta struct {
					Source       string `json:"source"`
					ResourceType string `json:"resource_type"`
				} `json:"meta"`
				Results []map[string]any `json:"results"`
			}
			if err := json.Unmarshal(out.Bytes(), &got); err != nil {
				t.Fatalf("parse output %q: %v", out.String(), err)
			}
			if got.Meta.Source != "local" {
				t.Fatalf("source = %q, want local", got.Meta.Source)
			}
			if got.Meta.ResourceType != command {
				t.Fatalf("resource_type = %q, want %q", got.Meta.ResourceType, command)
			}
			if len(got.Results) != 1 {
				t.Fatalf("results len = %d, want 1; output=%s", len(got.Results), out.String())
			}
			if len(got.Results[0]) == 0 {
				t.Fatalf("result compacted to an empty object; output=%s", out.String())
			}
		})
	}
}
